    try{const result=await data.onTrace(payload);if(destroyed)return;announce(typeof result?.message==='string'&&result.message?result.message.slice(0,1000):result?.ok===true?'An den gemeinsamen Spurenentwurf übergeben. Du entscheidest dort über die Speicherung.':'Die Übergabe wurde nicht ausgeführt. Deine Werkstattarbeit und der bestehende Entwurf bleiben erhalten.');}catch{if(!destroyed)announce('Die Übergabe ist gerade nicht möglich. Deine Werkstattarbeit bleibt erhalten.');}
