    const payload={format:'atlas-neuro-workbench',version:1,exportedAt:now(),provenance:{original:'Neuroatlas',commit:'35560b9',adaptation:'Gemeinsamer Atlas · Neuroatlas-Werkstatt',storage:'Nur ausdrücklich exportierte RAM-Arbeit; gemeinsame Originalspuren nicht enthalten.'},work};
